@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--bg:#071016;--panel:#0b171c;--line:#25373a;--acid:#d5fb63;--mint:#70e8c1;--muted:#779091;--paper:#eaf0d9;--orange:#ff7959}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--paper);font-family:'Space Grotesk',sans-serif}body{background-image:radial-gradient(ellipse at 50% 45%,#102329 0,transparent 58%),linear-gradient(90deg,transparent 49.9%,#11202755 50%,transparent 50.1%);overflow-x:hidden}.shell{width:min(1440px,100%);margin:0 auto;padding:24px 44px 18px}.topbar{height:44px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #26363a;color:var(--muted);font:10px 'DM Mono',monospace;letter-spacing:.13em}.brand{color:var(--paper);font:700 13px 'Space Grotesk',sans-serif;letter-spacing:.18em;text-decoration:none}.brand i{font-style:normal;color:var(--acid);font-size:10px}.brand-mark{color:var(--acid);font-size:18px;vertical-align:-2px;margin-right:8px}.edition{margin-left:54px}.edition span{color:var(--acid);padding:0 10px}.sound-toggle{border:0;background:none;color:var(--acid);font:10px 'DM Mono',monospace;letter-spacing:.12em;cursor:pointer}.sound-toggle span{color:var(--muted);margin-left:5px}.game-layout{display:grid;grid-template-columns:190px minmax(0,1fr) 190px;gap:24px;align-items:center;padding-top:34px}.side-panel{height:100%;min-height:575px;padding-top:22px;position:relative}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.16em;color:var(--mint);margin:0 0 16px}.left-panel h1{font-size:40px;line-height:.91;letter-spacing:-.07em;margin:0;font-weight:700}.left-panel h1 em{font-style:normal;color:var(--acid)}.tagline{font-size:19px;line-height:1.15;color:#a6b8ad;margin:14px 0 28px}.briefing{display:flex;gap:12px;align-items:flex-start;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;color:#91a5a1;font-size:10px;line-height:1.65}.briefing p{margin:0}.briefing b{font-weight:500;color:var(--paper)}.briefing-icon{font-size:23px;color:var(--acid);line-height:1}.howto{margin-top:32px}.howto .eyebrow{margin-bottom:11px}.key-row{display:flex;align-items:center;gap:6px;margin:8px 0;color:#91a5a1;font:9px 'DM Mono',monospace;letter-spacing:.13em}.key{display:inline-flex;align-items:center;justify-content:center;min-width:24px;height:23px;border:1px solid #455857;color:var(--paper);border-radius:3px;font-size:11px}.key.wide{width:53px;font-size:8px}.tiny-note{font:9px/1.6 'DM Mono',monospace;color:#607775;margin-top:24px}.cabinet{min-width:0;background:#0a1419;border:1px solid #314448;padding:9px;box-shadow:0 18px 70px #0008,0 0 0 4px #0a1419,0 0 0 5px #1e3034}.cabinet-top,.cabinet-foot{height:25px;display:flex;justify-content:space-between;align-items:center;padding:0 8px;color:#6d8584;font:9px 'DM Mono',monospace;letter-spacing:.12em}.live{color:#9bc1a3}.live i,.red-dot{display:inline-block;width:6px;height:6px;background:#a5fa70;border-radius:50%;box-shadow:0 0 8px #9dfc6a;margin-right:6px}.hud{height:54px;border-top:1px solid #23383b;border-bottom:1px solid #23383b;display:flex;align-items:center;justify-content:space-between;padding:0 15px}.hud-item{display:flex;flex-direction:column;gap:3px}.hud-label{font:8px 'DM Mono',monospace;letter-spacing:.17em;color:#779091}.hud-item strong{font:600 16px 'DM Mono',monospace;letter-spacing:.05em;color:var(--acid)}.lives-hud strong{color:var(--orange);font-size:13px;letter-spacing:.14em}.wave-hud strong{color:var(--mint)}.stage-wrap{position:relative;overflow:hidden;background:#071219;aspect-ratio:3/2}.stage-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(180deg,#0710168c,#071016d9);backdrop-filter:blur(2px);transition:opacity .22s}.screen.hidden{opacity:0;pointer-events:none}.screen-card{text-align:center;width:min(90%,420px);padding:29px 20px;position:relative;background:#0b181deb;border:1px solid #385051;box-shadow:0 12px 50px #0008}.intro-card{padding-top:24px}.stamp{position:absolute;top:11px;left:13px;font:8px 'DM Mono',monospace;letter-spacing:.12em;color:#78918d}.hero-alien{font-size:44px;color:var(--acid);line-height:1;margin:7px 0 12px;text-shadow:0 0 20px #c5f96866;animation:float 3s ease-in-out infinite}.screen-kicker{font:9px 'DM Mono',monospace;color:var(--mint);letter-spacing:.2em;margin:0 0 10px}.screen-card h2{font-size:38px;line-height:.91;letter-spacing:-.07em;margin:0 0 14px}.screen-card h2 span{color:var(--acid)}.screen-copy{font-size:12px;line-height:1.55;color:#a5b8b2;margin:0 auto 20px}.screen-copy i{color:var(--paper)}.primary-button{background:var(--acid);border:0;color:#13201c;font:700 10px 'DM Mono',monospace;letter-spacing:.12em;padding:13px 19px;min-width:185px;cursor:pointer;transition:transform .15s,background .15s}.primary-button:hover{background:#e6ff98;transform:translateY(-2px)}.primary-button span{font-size:15px;margin-left:12px}.microcopy{font:8px 'DM Mono',monospace;letter-spacing:.13em;color:#728783;margin:14px 0 0}.microcopy b{color:#d8e6d3;font-weight:400}.compact-card{width:min(90%,340px);padding:36px 20px}.compact-card h2{font-size:42px}.cabinet-foot{border-top:1px solid #23383b;margin-top:1px}.cabinet-foot span:first-child{color:var(--acid)}.cabinet-foot .coordinate{color:#4c6667}.dispatch-label{font:9px 'DM Mono',monospace;letter-spacing:.13em;color:#95a9a1}.red-dot{background:var(--orange);box-shadow:0 0 8px #ff7959}.dispatch-quote{font-size:28px;line-height:1.03;font-weight:600;letter-spacing:-.06em;margin-top:35px}.dispatch-quote em{font-weight:400;color:var(--acid)}.dispatch-by{font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#718783;margin-top:14px}.objective{border-top:1px solid var(--line);margin-top:33px;padding-top:18px}.objective .eyebrow{margin-bottom:11px}.objective-symbol{font-size:27px;color:var(--orange);line-height:1}.objective p:last-child{font-size:10px;line-height:1.7;color:#9eb0a9;margin:6px 0 0}.objective b{color:var(--paper);font-weight:500}.wave-status{position:absolute;bottom:15px;left:0;right:0}.wave-status .eyebrow{display:block;margin-bottom:9px}.threat-bars{display:flex;gap:3px;height:13px;align-items:end}.threat-bars i{display:block;width:11px;height:5px;background:#36514e}.threat-bars i:nth-child(2){height:7px}.threat-bars i:nth-child(3){height:9px}.threat-bars i:nth-child(4){height:11px}.threat-bars i:nth-child(5){height:13px}.threat-bars i:nth-child(6){height:13px}.threat-bars i:nth-child(7){height:13px}.threat-bars i.active{background:var(--orange);box-shadow:0 0 8px #ff795955}.wave-status>span:last-child{display:block;font:8px 'DM Mono',monospace;letter-spacing:.15em;color:#7a918c;margin-top:8px}footer{display:flex;justify-content:space-between;border-top:1px solid #26363a;margin-top:30px;padding-top:13px;color:#4f6868;font:8px 'DM Mono',monospace;letter-spacing:.13em}.touch-controls{display:none}
@keyframes float{50%{transform:translateY(-7px)}}
@media(max-width:1050px){.shell{padding:18px 24px}.game-layout{grid-template-columns:145px minmax(0,1fr) 145px;gap:16px}.left-panel h1{font-size:34px}.dispatch-quote{font-size:23px}.side-panel{min-height:520px}}
@media(max-width:760px){.shell{padding:12px 12px 15px}.topbar{height:34px}.edition{display:none}.brand{font-size:11px}.game-layout{display:block;padding-top:14px}.side-panel{display:none}.cabinet{padding:6px;box-shadow:0 8px 32px #0008,0 0 0 3px #0a1419,0 0 0 4px #1e3034}.cabinet-top,.cabinet-foot{height:22px;font-size:7px;padding:0 4px}.cabinet-foot span:nth-child(2){display:none}.hud{height:43px;padding:0 9px}.hud-label{font-size:7px}.hud-item strong{font-size:13px}.lives-hud strong{font-size:11px}.stage-wrap{aspect-ratio:3/2}.screen-card{padding:24px 12px}.intro-card{padding-top:21px}.hero-alien{font-size:34px;margin:3px 0 8px}.screen-card h2{font-size:31px}.screen-copy{font-size:10px;margin-bottom:14px}.screen-kicker{font-size:8px}.primary-button{padding:11px 12px;font-size:9px}.microcopy{font-size:7px}.touch-controls{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:17px 5px 0;color:#809793;font:8px 'DM Mono',monospace;letter-spacing:.1em}.touch-controls button{border:1px solid #3c5555;border-radius:4px;background:#0d1b20;color:var(--acid);height:45px;min-width:48px;font:24px 'Space Grotesk',sans-serif;touch-action:none}.touch-controls #fireButton{min-width:100px;background:#d5fb63;color:#102019;font:700 10px 'DM Mono',monospace;letter-spacing:.1em}.touch-controls #fireButton b{font-size:18px;vertical-align:-2px;margin-left:5px}.touch-controls span{flex:1;text-align:center}footer{margin-top:16px;font-size:7px;letter-spacing:.08em}footer span:nth-child(2){display:none}}
@media(max-height:700px) and (min-width:761px){.shell{padding-top:12px}.game-layout{padding-top:15px}.side-panel{min-height:490px}.cabinet-foot{height:20px}footer{margin-top:16px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 640;
  const $ = id => document.getElementById(id);
  const startScreen = $('startScreen'), pauseScreen = $('pauseScreen'), endScreen = $('endScreen');
  const scoreNode = $('score'), waveNode = $('wave'), livesNode = $('lives'), bestNode = $('best');
  const threatBars = [...document.querySelectorAll('.threat-bars i')];
  let state = 'intro', score = 0, wave = 1, lives = 3, best = 0;
  let lastTime = 0, frame = 0, soundOn = true, audio = null;
  let player, shots = [], enemyShots = [], particles = [], towers = [], stars = [], input = {left:false,right:false,fire:false}, pointerDown = false;
  try { best = Number(localStorage.getItem('invasionShiftBest') || 0); } catch (_) {}
  bestNode.textContent = pad(best);

  function pad(n){ return String(Math.max(0, Math.floor(n))).padStart(6,'0'); }
  function updateHud(){
    scoreNode.textContent = pad(score); waveNode.textContent = String(wave).padStart(2,'0');
    livesNode.textContent = Array.from({length:3},(_,i)=>i<lives?'◆':'◇').join(' ');
    livesNode.setAttribute('aria-label', `${lives} lives remaining`); bestNode.textContent = pad(best);
    const level = Math.min(7, 1 + Math.floor((wave-1)/1.4));
    threatBars.forEach((bar,i)=>bar.classList.toggle('active', i<level));
    $('threatText').textContent = wave<2?'LOW ORBIT':wave<4?'HOSTILE SKIES':wave<7?'FULL LOCK':'PLANETARY PANIC';
  }
  function sound(freq=420,duration=.08,type='square',volume=.035){
    if(!soundOn)return;
    try{
      audio ||= new (window.AudioContext||window.webkitAudioContext)();
      if(audio.state==='suspended') audio.resume();
      const osc=audio.createOscillator(), gain=audio.createGain();
      osc.type=type; osc.frequency.setValueAtTime(freq,audio.currentTime);
      gain.gain.setValueAtTime(volume,audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);
      osc.connect(gain); gain.connect(audio.destination); osc.start(); osc.stop(audio.currentTime+duration);
    }catch(_){/* Audio is optional. */}
  }
  function resetGame(){
    score=0; wave=1; lives=3; shots=[]; enemyShots=[]; particles=[];
    player={x:W/2,y:100,r:19,speed:370,cooldown:0,invuln:0};
    spawnWave(); updateHud(); state='playing'; startScreen.classList.add('hidden');pauseScreen.classList.add('hidden');endScreen.classList.add('hidden');
  }
  function spawnWave(){
    towers=[]; const count=Math.min(4+Math.floor(wave*.8),9);
    const gap=760/(count-1 || 1);
    for(let i=0;i<count;i++) towers.push({x:100+i*gap,y:490+(i%2)*37,hp:1+(wave>2&&i%3===0?1:0),max:1+(wave>2&&i%3===0?1:0),phase:Math.random()*8,cooldown:.5+Math.random()*1.6});
    shots=[];enemyShots=[];
  }
  function beginWave(){
    wave++; spawnWave(); updateHud(); state='playing';
    particles.push({x:W/2,y:270,text:`WAVE ${String(wave).padStart(2,'0')}`,life:1.6,max:1.6,color:'#d5fb63'});
  }
  function finishGame(won){
    state='over'; input.fire=false; input.left=input.right=false;
    $('endKicker').textContent=won?'TRANSMISSION RECEIVED':'SIGNAL LOST';
    $('endTitle').innerHTML=won?'EARTH<br/>SURRENDERS<span>!</span>':'EARTH<br/>WINS<span>?</span>';
    $('endCopy').textContent=won?'You made contact. The welcome committee was… surprisingly loud.':`You scored ${pad(score)} points. The cosmos is rooting for a rematch.`;
    $('restartButton').innerHTML=(won?'EXPLORE AGAIN':'RUN IT BACK')+' <span>↗</span>';
    endScreen.classList.remove('hidden');
  }
  function addScore(n){score+=n;if(score>best){best=score;try{localStorage.setItem('invasionShiftBest',String(best));}catch(_){}}updateHud();}
  function burst(x,y,color,count=9){
    for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*150;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.3+Math.random()*.55,max:.85,size:1.5+Math.random()*3,color});}
  }
  function fire(){
    if(player.cooldown>0)return;
    shots.push({x:player.x,y:player.y+20,vy:520}); player.cooldown=.18;
    sound(540,.07,'square',.018);
  }
  function fireEnemy(t){
    const dx=player.x-t.x,dy=player.y-t.y,len=Math.hypot(dx,dy)||1,speed=170+wave*11;
    enemyShots.push({x:t.x,y:t.y-18,vx:dx/len*speed*.35,vy:-Math.abs(dy/len*speed)-45});
    sound(145,.11,'sawtooth',.012);
  }
  function hitPlayer(){
    if(player.invuln>0)return;
    lives--;player.invuln=1.5;burst(player.x,player.y,'#ff7959',20);sound(90,.3,'sawtooth',.05);updateHud();
    if(lives<=0)finishGame(false);
  }
  function update(dt){
    frame+=dt;
    if(state!=='playing')return;
    player.invuln=Math.max(0,player.invuln-dt);player.cooldown=Math.max(0,player.cooldown-dt);
    if(input.left)player.x-=player.speed*dt;
    if(input.right)player.x+=player.speed*dt;
    player.x=Math.max(30,Math.min(W-30,player.x));
    if(input.fire)fire();
    for(const t of towers){t.phase+=dt;t.cooldown-=dt;if(t.cooldown<=0){fireEnemy(t);t.cooldown=Math.max(.56,1.8-wave*.09)+Math.random()*.9;}}
    for(const s of shots)s.y+=s.vy*dt;
    shots=shots.filter(s=>s.y<H+20);
    for(const s of enemyShots){s.x+=s.vx*dt;s.y+=s.vy*dt;}
    enemyShots=enemyShots.filter(s=>s.y>-25&&s.x>-30&&s.x<W+30);
    for(let i=shots.length-1;i>=0;i--){const s=shots[i];let hit=false;
      for(let j=towers.length-1;j>=0;j--){const t=towers[j];if(Math.abs(s.x-t.x)<25&&Math.abs(s.y-t.y)<25){t.hp--;hit=true;burst(s.x,s.y,'#70e8c1',5);if(t.hp<=0){burst(t.x,t.y,'#ffb35c',16);towers.splice(j,1);addScore(120+wave*15);sound(250,.14,'triangle',.04);}else sound(300,.06,'triangle',.02);break;}}
      if(hit)shots.splice(i,1);
    }
    for(let i=enemyShots.length-1;i>=0;i--){const s=enemyShots[i];if(Math.hypot(s.x-player.x,s.y-player.y)<23){enemyShots.splice(i,1);hitPlayer();}}
    if(towers.length===0){state='waveclear';particles.push({x:W/2,y:285,text:'GRID OFFLINE',life:1.3,max:1.3,color:'#70e8c1'});sound(660,.2,'triangle',.04);setTimeout(()=>{if(state==='waveclear')beginWave();},1250);}
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.vx!==undefined){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=75*dt;}if(p.life<=0)particles.splice(i,1);}
  }
  function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
  function drawBackground(){
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#08151e');g.addColorStop(.68,'#101d20');g.addColorStop(1,'#17221d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // distant aurora haze
    const haze=ctx.createRadialGradient(510,330,25,510,330,440);haze.addColorStop(0,'#17373a55');haze.addColorStop(1,'#17373a00');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
    for(let i=0;i<80;i++){const x=(i*173+31)%W,y=(i*89+17)%435;const twinkle=.35+.65*Math.sin(frame*1.5+i*4)**2;ctx.fillStyle=`rgba(190,230,202,${.18*twinkle})`;ctx.fillRect(x,y,((i%3)+1)*.7,.8);}
    // horizon and city silhouettes
    ctx.fillStyle='#111c1b';ctx.beginPath();ctx.moveTo(0,480);
    let x=0;while(x<=W){const width=24+(Math.sin(x*.071)*.5+.5)*39,height=38+(Math.sin(x*.027+2)*.5+.5)*105;ctx.lineTo(x,480-height);ctx.lineTo(x+width*.72,480-height);ctx.lineTo(x+width*.72,480);x+=width;}
    ctx.lineTo(W,540);ctx.lineTo(0,540);ctx.closePath();ctx.fill();
    ctx.fillStyle='#24302a';ctx.fillRect(0,541,W,99);
    ctx.fillStyle='#d5fb6333';ctx.fillRect(0,540,W,1);
    for(let b=0;b<24;b++){const bx=b*43+6,bh=22+(b*17%70);ctx.fillStyle=b%3?'#1b2b27':'#27382d';ctx.fillRect(bx,540-bh,29,bh);for(let wy=550-bh;wy<530;wy+=12)for(let wx=bx+5;wx<bx+26;wx+=10){ctx.fillStyle=((b*3+wy+wx)%5===0)?'#d5fb6370':'#88d2a226';ctx.fillRect(wx,wy,3,4);}}
    ctx.strokeStyle='#34443a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,594);ctx.lineTo(W,594);ctx.stroke();
    ctx.fillStyle='#718375';ctx.font='10px monospace';ctx.fillText('NEW YORK // DEFENSE GRID',18,615);ctx.textAlign='right';ctx.fillText('POP. 8,804,190',W-18,615);ctx.textAlign='left';
  }
  function drawPlayer(){
    if(!player)return; if(player.invuln>0&&Math.floor(frame*12)%2===0)return;
    ctx.save();ctx.translate(player.x,player.y);ctx.shadowColor='#d5fb63';ctx.shadowBlur=20;
    // tractor glow
    const beam=ctx.createLinearGradient(0,10,0,72);beam.addColorStop(0,'#d5fb6340');beam.addColorStop(1,'#d5fb6300');ctx.fillStyle=beam;ctx.beginPath();ctx.moveTo(-12,12);ctx.lineTo(12,12);ctx.lineTo(29,70);ctx.lineTo(-29,70);ctx.fill();
    ctx.fillStyle='#c9f768';ctx.beginPath();ctx.moveTo(-28,3);ctx.quadraticCurveTo(-22,-7,0,-12);ctx.quadraticCurveTo(22,-7,28,3);ctx.lineTo(39,9);ctx.quadraticCurveTo(0,24,-39,9);ctx.closePath();ctx.fill();
    ctx.fillStyle='#304d34';ctx.beginPath();ctx.ellipse(0,-5,13,9,0,Math.PI,0);ctx.fill();ctx.fillStyle='#ddff9b';ctx.fillRect(-21,7,5,2);ctx.fillRect(16,7,5,2);
    ctx.restore();
  }
  function drawTower(t){
    ctx.save();ctx.translate(t.x,t.y);ctx.fillStyle='#263a37';ctx.strokeStyle='#85aa81';ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(-22,18);ctx.lineTo(-19,-8);ctx.lineTo(-11,-17);ctx.lineTo(11,-17);ctx.lineTo(19,-8);ctx.lineTo(22,18);ctx.closePath();ctx.fill();ctx.stroke();
    ctx.fillStyle='#ff7959';ctx.shadowColor='#ff7959';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(0,-8,5+Math.sin(t.phase*5)*1.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#7d4035';roundRect(-21,23,42,4,2);ctx.fill();ctx.fillStyle='#ff7959';roundRect(-20,24,40*t.hp/t.max,2,1);ctx.fill();
    for(let k=0;k<3;k++){ctx.fillStyle='#a5cf8b';ctx.fillRect(-13+k*12,7,4,4);}
    ctx.restore();
  }
  function draw(){
    ctx.clearRect(0,0,W,H);drawBackground();
    // subtle targeting grid
    ctx.strokeStyle='#8cc6a00b';ctx.lineWidth=1;for(let x=40;x<W;x+=80){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,460);ctx.stroke();}
    ctx.fillStyle='#9dd8ff';for(const s of shots){ctx.shadowColor='#d5fb63';ctx.shadowBlur=12;roundRect(s.x-2,s.y-10,4,16,2);ctx.fillStyle='#e7ffad';ctx.fill();ctx.shadowBlur=0;}
    for(const s of enemyShots){ctx.fillStyle='#ff7959';ctx.shadowColor='#ff7959';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(s.x,s.y,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd2a8';ctx.beginPath();ctx.arc(s.x,s.y,1.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}
    for(const t of towers)drawTower(t);drawPlayer();
    for(const p of particles){if(p.text){ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillStyle=p.color;ctx.textAlign='center';ctx.font='bold 22px monospace';ctx.fillText(p.text,p.x,p.y);ctx.textAlign='left';ctx.globalAlpha=1;}else{ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.globalAlpha=1;}}
    if(state==='waveclear'){ctx.fillStyle='#70e8c1';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('INCOMING TRANSMISSION…',W/2,320);ctx.textAlign='left';}
  }
  function loop(now){const dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;update(dt);draw();requestAnimationFrame(loop);}
